+          for (var i = 0; i <= 10; i++) {
+            var gx = area.left + (area.right - area.left) * (i / 10);
+            ctx.beginPath();
+            ctx.moveTo(gx, area.top);
+            ctx.lineTo(gx, area.bottom);
+            ctx.stroke();
+          }
+          ctx.setLineDash([]);
