+          var govX = area.left + 6;
+          var govW = area.right - area.left - 12;
+          ctx.beginPath();
+          ctx.roundRect(govX, govY, govW, govH, 10);
+          ctx.fillStyle = isDark ? 'rgba(139,92,246,0.14)' : 'rgba(124,58,237,0.12)';
+          ctx.fill();
+          ctx.strokeStyle = isDark ? 'rgba(139,92,246,0.35)' : 'rgba(124,58,237,0.30)';
+          ctx.lineWidth = 1;
+          ctx.stroke();
+          ctx.fillStyle = textColor;
+          ctx.font = '600 12px Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif';
+          ctx.fillText('Governance overlay: access control, quality gates, lineage (cross-layer)', govX + 14, govY + 26);
+          ctx.font = '400 11px Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif';
+          ctx.fillStyle = isDark ? 'rgba(237,237,237,0.72)' : 'rgba(15,23,42,0.72)';
+          ctx.fillText('15 controls total, including 3 cross-layer mechanisms', govX + 14, govY + 40);
+
+          function toPxX(nx) { return area.left + nx * (area.right - area.left); }
+          function toPxY(ny) { return area.top + ny * (area.bottom - area.top); }
+
+          // Links
+          links.forEach(function(l) {
+            var a = nodeById[l.from];
+            var b = nodeById[l.to];
+            if (!a || !b) return;
+            var x1 = toPxX(a.x);
+            var y1 = toPxY(a.y);
+            var x2 = toPxX(b.x);
+            var y2 = toPxY(b.y);
+            var cp1x = x1 + (x2 - x1) * 0.35;
+            var cp2x = x1 + (x2 - x1) * 0.65;
+
+            ctx.beginPath();
+            ctx.moveTo(x1, y1);
+            ctx.bezierCurveTo(cp1x, y1, cp2x, y2, x2, y2);
+            ctx.strokeStyle = rgba(l.color, isDark ? 0.62 : 0.55);
+            ctx.lineWidth = w(l.v);
+            ctx.lineCap = 'round';
+            ctx.stroke();
+          });
+
+          // Nodes + labels
+          nodes.forEach(function(n) {
+            var x = toPxX(n.x);
+            var y = toPxY(n.y);
+            var r = 8;
+            ctx.beginPath();
+            ctx.arc(x, y, r, 0, Math.PI * 2);
+            ctx.fillStyle = n.color;
+            ctx.fill();
+            ctx.strokeStyle = isDark ? 'rgba(255,255,255,0.18)' : 'rgba(0,0,0,0.10)';
+            ctx.lineWidth = 1;
+            ctx.stroke();
+
+            ctx.fillStyle = textColor;
+            ctx.font = '600 12px Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif';
+            var lines = String(n.label).split('\n');
+            var align = n.x < 0.5 ? 'left' : 'right';
+            if (Math.abs(n.x - 0.78) < 0.01) align = 'center';
+            if (Math.abs(n.x - 0.47) < 0.01) align = 'center';
+            if (Math.abs(n.x - 0.64) < 0.01) align = 'center';
