+            var ty = y - (lines.length - 1) * 8;
+            for (var i = 0; i < lines.length; i++) {
+              ctx.fillText(lines[i], tx, ty + i * 16);
+            }
+          });
+
+          // Stage axis labels
+          ctx.textAlign = 'center';
+          ctx.textBaseline = 'alphabetic';
+          ctx.fillStyle = isDark ? 'rgba(237,237,237,0.78)' : 'rgba(15,23,42,0.78)';
+          ctx.font = '600 11px Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif';
+          var labels = [
+            { t: 'Sources', x: 0.08 },
+            { t: 'Ingestion', x: 0.29 },
+            { t: 'Bronze', x: 0.47 },
+            { t: 'Silver', x: 0.64 },
+            { t: 'Gold', x: 0.78 },
+            { t: 'Consumption', x: 0.92 }
+          ];
+          labels.forEach(function(lab) {
+            ctx.fillText(lab.t, area.left + (area.right - area.left) * lab.x, area.bottom - 10);
+          });
+
+          ctx.restore();
+        }
+      };
+
+      var config = {
+        type: 'scatter',
+        data: {
+          datasets: [{
+            label: 'Lakehouse pipeline nodes',
+            data: nodes.map(function(n) { return ({ x: n.x, y: n.y }); }),
+            pointRadius: 0
+          }]
+        },
+        options: {
+          responsive: true,
+          maintainAspectRatio: false,
+          animation: false,
+          plugins: {
