const fs = require('fs');
const path = require('path');
const playwright = (()=>{ try { return require('playwright'); } catch(e){ return null; }})();

(async () => {
  const htmlPath = path.resolve('output/lakehouse-pipeline-sankey.html');
  const outPath = path.resolve('output/result.png');
  if (!playwright) {
    console.error('Playwright not installed');
    process.exit(2);
  }
  const { chromium } = playwright;
  const browser = await chromium.launch({ args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1400, height: 900, deviceScaleFactor: 2 } });
  await page.goto('file://' + htmlPath, { waitUntil: 'load' });
  await page.waitForTimeout(400);
  // Ensure light theme for business audience
  await page.evaluate(() => {
    try { localStorage.setItem('viz-theme','light'); } catch(e) {}
    if (typeof applyTheme === 'function') applyTheme('light');
  });
  await page.waitForTimeout(300);
  // Wait for canvas paint
  await page.waitForTimeout(300);
  // Screenshot main visualization section
  const main = await page.$('section.page');
  if (!main) {
    console.error('Main section not found');
    process.exit(3);
  }
  await main.screenshot({ path: outPath });
  await browser.close();
  console.log('Wrote', outPath);
})();
